package com.example.bandlink.controller; import com.example.bandlink.dto.ReportRequest; import com.example.bandlink.repository.UserRepository; import com.example.bandlink.service.ReportService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/reports") public class ReportController{private final ReportService service;private final UserRepository users;public ReportController(ReportService s,UserRepository u){service=s;users=u;}@PostMapping public void create(Authentication a,@Valid @RequestBody ReportRequest r){service.create(users.findByEmail(a.getName()).orElseThrow().getId(),r);}}
